head.script:
scwin.refreshTextbox = function() {
    var rowStatusTxt = "";
    var json1 = dataList1.getAllJSON();
    var json2 = dataList2.getAllJSON();
    rowStatusTxt += "[dataList1]\n";
    for (var i = 0; i < json1.length; i++) {
        rowStatusTxt += json1[i].rowStatus + "\n";
    }
    rowStatusTxt += "\n[dataList2]\n";
    for (var j = 0; j < json2.length; j++) {
        rowStatusTxt += json2[j].rowStatus + "\n";
    }
    textbox1.setValue(rowStatusTxt);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView2__col2', 'key-sequence', {
        sequence: '1'
    });
}
scwin.compareTwoArrays = function(arr1, arr2) {
    return arr1.length == arr2.length && arr1.every(function(v, i) {
        return v === arr2[i]
    })
}
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_1_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_0').click()");
    //Verify step 5. RowStatus 가 Update / Update 로 변경된다.
    //5. RowStatus changes to Update / Update.
    WebSquare.wUnit.addCommand("assert", "scwin.compareTwoArrays(WebSquare.wUnit.getObjById('dataList2').rowStatusArr, ['U', 'U'])", "true");
    //Test step 6. dataList2.setData 버튼을 클릭한다.
    //6. Click the dataList2.setData button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "valBeforeChange = WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "valAfterChange = WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText");
    //Verify step 6. dataList2 의 데이터가 변경된다.
    //6. The data in dataList2 is changed.
    WebSquare.wUnit.addCommand("assert", "valBeforeChange != valAfterChange", "true");
