    //7. Optionally modify the dataList2 column.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_1_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_2_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_3_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_0').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.compareTwoArrays(WebSquare.wUnit.getObjById('dataList2').rowStatusArr, ['D', 'U', 'D', 'U'])", "true");
    //Test step 8. 브라우저에서 dataList2.setXML 버튼을 클릭한다.
    //8. In your browser, click the dataList2.setXML button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "valBeforeChange = WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "valAfterChange = WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText");
    //Verify step 8. dataList2 의 데이터가 변경된다.
    //8. The data in dataList2 is changed.
    WebSquare.wUnit.addCommand("assert", "valBeforeChange != valAfterChange", "true");
    //Test step 9. 임의로 dataList2 컬럼을 수정한다.
    //9. Optionally modify the dataList2 column.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_1_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_2_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_3_1')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_0').click()");
    //Verify step 9. RowStatus 가 U / U / U / U로 변경된다.
    //9. RowStatus is changed to U / U / U / U.
    WebSquare.wUnit.addCommand("assert", "scwin.compareTwoArrays(WebSquare.wUnit.getObjById('dataList2').rowStatusArr, ['U', 'U', 'U', 'U'])", "true");
    //Test step 10. 브라우저에서 dataList2.setJSON 버튼을 클릭한다.
    //10. In your browser, click the dataList2.setJSON button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "valBeforeChange = WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText");
